package app.velyntora.windows.canvas;
import art.velyntora.core.*;
import app.velyntora.windows.tools.Tool;
import javax.swing.*;
import java.awt.*;
import java.awt.event.*;
import java.awt.geom.*;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
public final class CanvasPanel extends JPanel {
 public Tool tool=Tool.BRUSH;public int color=0xff000000,secondary=0xffffffff,size=8,tolerance=24;public float opacity=1;public boolean filled=false;public BrushPresets.Preset preset;
 private BufferedImage removal;private long removalRevision=-1;private int removalLayer=-1;
 public byte[] selection;private Rectangle selectionBounds;private final ArrayList<Point2D.Double> curve=new ArrayList<>();private final java.util.Map<Point2D.Double,Float> tensions=new java.util.IdentityHashMap<>();private final ArrayList<ArrayList<Point2D.Double>> otherCurves=new ArrayList<>(),committedOthers=new ArrayList<>();private int curveNode=-1;private final ArrayList<Point2D.Double> lasso=new ArrayList<>(),committedCurve=new ArrayList<>();private long curveBefore=-1;
 public double zoom=1,rotation=0,offsetX=40,offsetY=40;private Point2D.Double start,last,current;private Point pan;private boolean dragging,painting;private int cloneX,cloneY;private final Runnable changed;private BufferedImage image;private boolean invalid=true;
 public CanvasPanel(Runnable changed){this.changed=changed;setBackground(new Color(62,62,66));setFocusable(true);
  MouseAdapter input=new MouseAdapter(){
   public void mousePressed(MouseEvent e){requestFocusInWindow();if(SwingUtilities.isMiddleMouseButton(e)||tool==Tool.PAN){pan=e.getPoint();return;}Point2D.Double p=point(e);start=last=current=p;if(p==null)return;
    if(tool==Tool.REMOVE_AI){mask(p,p);dragging=true;return;}if(tool==Tool.MOVE_PIXELS&&selection==null)selectAll();if(tool==Tool.CLONE&&e.isAltDown()){cloneX=(int)p.x;cloneY=(int)p.y;return;}
    if(tool==Tool.ZOOM){setZoom(zoom*(e.isShiftDown()?.8:1.25),e.getPoint());return;}
    if(tool==Tool.PICKER){color=DrawingView.nativePickColor((int)p.x,(int)p.y);changed.run();return;}
    if(tool==Tool.WAND){wand((int)p.x,(int)p.y);return;}
    if(tool==Tool.FILL){DrawingView.nativeFillSelectionWorker((int)p.x,(int)p.y,color,opacity,selection);refresh();return;}
    if(tool==Tool.TEXT){text(p);return;}
    if(tool==Tool.LINE){if(curve.isEmpty()){curve.add(p);curve.add(new Point2D.Double(p.x,p.y));curveNode=1;}else{curveNode=-1;for(int i=0;i<curve.size();i++)if(curve.get(i).distance(p)*zoom<12)curveNode=i;if(curveNode<0){int insert=DesktopCurves.insertIndex(curve,p,(float)(10/zoom),tensions);if(insert<0){otherCurves.add(new ArrayList<>(curve));curve.clear();curve.add(p);curve.add(new Point2D.Double(p.x,p.y));curveNode=1;}else{curve.add(insert,p);curveNode=insert;}}else if(SwingUtilities.isRightMouseButton(e)){JSlider tension=new JSlider(0,100,Math.round(tensions.getOrDefault(curve.get(curveNode),curveNode==0||curveNode==curve.size()-1?0f:1f/3f)*100));if(JOptionPane.showConfirmDialog(CanvasPanel.this,tension,"Tensión del punto",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION)tensions.put(curve.get(curveNode),tension.getValue()/100f);repaint();return;}}dragging=true;return;}
    dragging=true;if(tool==Tool.FREEFORM){lasso.clear();lasso.add(p);}if(tool==Tool.LASSO){lasso.clear();lasso.add(p);}if(tool==Tool.BRUSH||tool==Tool.PENCIL||tool==Tool.ERASER||tool==Tool.CLONE||tool==Tool.RECOLOR){DrawingView.nativeBeginEdit();DrawingView.nativeSetBrushSelection(selection);DrawingView.nativeBeginOpacityStroke(true);if(preset!=null&&tool==Tool.BRUSH)BrushPresets.begin(preset);if(tool==Tool.CLONE||tool==Tool.RECOLOR)DrawingView.nativeBeginSampled((int)p.x,(int)p.y);painting=true;stroke(p,p);}
   }
   public void mouseDragged(MouseEvent e){if(pan!=null){offsetX+=e.getX()-pan.x;offsetY+=e.getY()-pan.y;pan=e.getPoint();repaint();return;}if(!dragging)return;Point2D.Double p=point(e);if(p==null)return;current=p;if(tool==Tool.REMOVE_AI){mask(last,p);last=p;repaint();return;}if(tool==Tool.FREEFORM)lasso.add(p);if(tool==Tool.LASSO)lasso.add(p);if(tool==Tool.LINE&&curveNode>=0){Float tension=tensions.remove(curve.get(curveNode));curve.set(curveNode,p);if(tension!=null)tensions.put(p,tension);}else if(painting)stroke(last,p);last=p;repaint();}
   public void mouseReleased(MouseEvent e){if(pan!=null){pan=null;return;}if(!dragging)return;dragging=false;if(painting){painting=false;DrawingView.nativeEndOpacityStroke();refresh();return;}if(tool==Tool.REMOVE_AI){repaint();return;}if(tool==Tool.LINE){repaint();return;}if(tool==Tool.SELECT||tool==Tool.ELLIPSE_SELECT||tool==Tool.LASSO){select();return;}if((tool==Tool.MOVE||tool==Tool.MOVE_PIXELS)&&selectionBounds!=null){Rectangle b=selectionBounds;byte[] mask=new byte[b.width*b.height];for(int y=0;y<b.height;y++)System.arraycopy(selection,(b.y+y)*DrawingView.nativeWidth()+b.x,mask,y*b.width,b.width);int dx=(int)(current.x-start.x),dy=(int)(current.y-start.y);DrawingView.nativeMoveMaskedSelection(b.x,b.y,b.width,b.height,mask,dx,dy);clearSelection();refresh();return;}shape();}
   public void mouseWheelMoved(MouseWheelEvent e){if(e.isAltDown()){rotation+=e.getPreciseWheelRotation()*Math.PI/36;repaint();}else setZoom(zoom*Math.pow(1.15,-e.getPreciseWheelRotation()),e.getPoint());}
  };addMouseListener(input);addMouseMotionListener(input);addMouseWheelListener(input);
 }
 private AffineTransform transform(){AffineTransform t=new AffineTransform();t.translate(offsetX,offsetY);t.scale(zoom,zoom);t.rotate(rotation,DrawingView.nativeWidth()/2.,DrawingView.nativeHeight()/2.);return t;}
 private Point2D.Double point(MouseEvent e){try{Point2D p=transform().inverseTransform(e.getPoint(),null);return new Point2D.Double(p.getX(),p.getY());}catch(Exception ex){return null;}}
 public void setZoom(double value,Point anchor){try{Point2D p=transform().inverseTransform(anchor,null);zoom=Math.max(.02,Math.min(70,value));Point2D now=transform().transform(p,null);offsetX+=anchor.x-now.getX();offsetY+=anchor.y-now.getY();}catch(Exception ignored){}repaint();changed.run();}
 public void fit(){int w=DrawingView.nativeWidth(),h=DrawingView.nativeHeight();zoom=Math.min((getWidth()-60.)/w,(getHeight()-60.)/h);zoom=Math.max(.02,zoom);offsetX=(getWidth()-w*zoom)/2;offsetY=(getHeight()-h*zoom)/2;rotation=0;repaint();}
 public void refresh(){invalid=true;changed.run();repaint();}
 private void stroke(Point2D.Double a,Point2D.Double b){float pressure=DrawingView.nativePointerPressure();float r=size/2f*(tool==Tool.BRUSH&&preset!=null?1:Math.max(.03f,pressure));if(tool==Tool.PENCIL)r=Math.max(.5f,r);
  if(tool==Tool.CLONE||tool==Tool.RECOLOR)DrawingView.nativeSampledStroke(tool==Tool.CLONE,cloneX-(int)start.x,cloneY-(int)start.y,color,tolerance,(float)a.x,(float)a.y,(float)b.x,(float)b.y,r,opacity,1);
  else if(preset!=null&&tool==Tool.BRUSH)DrawingView.nativeTipBrushStroke((float)a.x,(float)a.y,(float)b.x,(float)b.y,r,color,opacity,pressure);
  else DrawingView.nativeStyledStroke((float)a.x,(float)a.y,(float)b.x,(float)b.y,r,color,opacity,tool==Tool.PENCIL?1:.85f,tool==Tool.PENCIL,tool==Tool.ERASER);
  invalid=true;repaint();
 }
 private Rectangle dragBounds(){int w=DrawingView.nativeWidth(),h=DrawingView.nativeHeight();int x=Math.max(0,(int)Math.min(start.x,current.x)),y=Math.max(0,(int)Math.min(start.y,current.y));return new Rectangle(x,y,Math.max(0,Math.min(w,(int)Math.max(start.x,current.x)+1)-x),Math.max(0,Math.min(h,(int)Math.max(start.y,current.y)+1)-y));}
 private void select(){Rectangle b=tool==Tool.LASSO?lassoPath().getBounds().intersection(new Rectangle(0,0,DrawingView.nativeWidth(),DrawingView.nativeHeight())):dragBounds();selection=new byte[DrawingView.nativeWidth()*DrawingView.nativeHeight()];for(int y=b.y;y<b.y+b.height;y++)for(int x=b.x;x<b.x+b.width;x++){double xx=(x-b.getCenterX())/Math.max(1,b.width/2.),yy=(y-b.getCenterY())/Math.max(1,b.height/2.);if((tool==Tool.LASSO?lassoPath().contains(x,y):tool!=Tool.ELLIPSE_SELECT||xx*xx+yy*yy<=1))selection[y*DrawingView.nativeWidth()+x]=1;}selectionBounds=b;repaint();}
 private void wand(int x,int y){int w=DrawingView.nativeWidth(),h=DrawingView.nativeHeight();if(x<0||y<0||x>=w||y>=h)return;int[] pixels=DrawingView.nativePixels();selection=new byte[w*h];java.util.ArrayDeque<Integer> queue=new java.util.ArrayDeque<>();int target=pixels[y*w+x];queue.add(y*w+x);selection[y*w+x]=1;while(!queue.isEmpty()){int i=queue.removeFirst(),ix=i%w;int[] next={ix>0?i-1:-1,ix<w-1?i+1:-1,i-w,i+w};for(int n:next)if(n>=0&&n<pixels.length&&selection[n]==0){int v=pixels[n];if(Math.max(Math.max(Math.abs((v>>>24)-(target>>>24)),Math.abs((v>>16&255)-(target>>16&255))),Math.max(Math.abs((v>>8&255)-(target>>8&255)),Math.abs((v&255)-(target&255))))<=tolerance){selection[n]=1;queue.add(n);}}}selectionBounds=new Rectangle(0,0,w,h);repaint();}
 private Path2D lassoPath(){Path2D p=new Path2D.Double();if(lasso.isEmpty())return p;p.moveTo(lasso.get(0).x,lasso.get(0).y);for(Point2D.Double a:lasso)p.lineTo(a.x,a.y);p.closePath();return p;}
 public void selectAll(){selection=new byte[DrawingView.nativeWidth()*DrawingView.nativeHeight()];java.util.Arrays.fill(selection,(byte)1);selectionBounds=new Rectangle(0,0,DrawingView.nativeWidth(),DrawingView.nativeHeight());repaint();}
 public int[] copySelection(){Rectangle b=selectionBounds==null?new Rectangle(0,0,DrawingView.nativeWidth(),DrawingView.nativeHeight()):selectionBounds;int[] data=DrawingView.nativeCopySelection(9,b.x,b.y,b.x+b.width,b.y+b.height);if(data!=null&&selection!=null)for(int y=0;y<b.height;y++)for(int x=0;x<b.width;x++)if(selection[(b.y+y)*DrawingView.nativeWidth()+b.x+x]==0)data[2+y*b.width+x]=0;return data;}
 public void clearSelection(){selection=null;selectionBounds=null;DrawingView.nativeSetBrushSelection(null);repaint();}
 public void deleteSelection(){if(selectionBounds!=null){Rectangle b=selectionBounds;byte[] mask=new byte[b.width*b.height];for(int y=0;y<b.height;y++)System.arraycopy(selection,(b.y+y)*DrawingView.nativeWidth()+b.x,mask,y*b.width,b.width);DrawingView.nativeEraseMaskedSelection(b.x,b.y,b.width,b.height,mask);}else DrawingView.nativeClear();refresh();}
 private Shape shapePath(){Rectangle b=dragBounds();if(tool==Tool.FREEFORM)return lassoPath();if(tool==Tool.CIRCLE){int side=Math.max(b.width,b.height);return new Ellipse2D.Double(b.x,b.y,side,side);}if(tool==Tool.ELLIPSE)return new Ellipse2D.Double(b.x,b.y,b.width,b.height);if(tool==Tool.ROUNDRECT)return new RoundRectangle2D.Double(b.x,b.y,b.width,b.height,20,20);if(tool==Tool.TRIANGLE){Path2D p=new Path2D.Double();p.moveTo(b.getCenterX(),b.y);p.lineTo(b.x+b.width,b.y+b.height);p.lineTo(b.x,b.y+b.height);p.closePath();return p;}return b;}
 private void shape(){Rectangle b=tool==Tool.FREEFORM?lassoPath().getBounds():tool==Tool.CIRCLE?shapePath().getBounds():dragBounds();if(b.width<1||b.height<1)return;if(tool==Tool.GRADIENT){BufferedImage stamp=new BufferedImage(b.width,b.height,BufferedImage.TYPE_INT_ARGB);Graphics2D g=stamp.createGraphics();g.setPaint(new GradientPaint(0,0,new Color(color,true),b.width,b.height,new Color(secondary,true)));g.fillRect(0,0,b.width,b.height);g.dispose();paste(stamp,b.x,b.y);return;}if(tool!=Tool.RECT&&tool!=Tool.ELLIPSE&&tool!=Tool.ROUNDRECT&&tool!=Tool.TRIANGLE&&tool!=Tool.CIRCLE&&tool!=Tool.FREEFORM)return;BufferedImage stamp=new BufferedImage(b.width+size+2,b.height+size+2,BufferedImage.TYPE_INT_ARGB);Graphics2D g=stamp.createGraphics();g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);g.translate(-b.x+size/2.,-b.y+size/2.);g.setColor(new Color(color,true));g.setComposite(AlphaComposite.SrcOver.derive(opacity));g.setStroke(new BasicStroke(size));if(filled)g.fill(shapePath());else g.draw(tool==Tool.LASSO?lassoPath():shapePath());g.dispose();paste(stamp,b.x-size/2,b.y-size/2);}
 private void paste(BufferedImage stamp,int x,int y){int w=stamp.getWidth(),h=stamp.getHeight();int[] data=new int[2+w*h];data[0]=w;data[1]=h;stamp.getRGB(0,0,w,h,data,2,w);DrawingView.nativePasteSelection(data,x,y);refresh();}
 private void text(Point2D.Double p){app.velyntora.windows.objects.ObjectEditor.text((javax.swing.JFrame)SwingUtilities.getWindowAncestor(this),color,size,(int)p.x,(int)p.y,this::refresh);}
 private void mask(Point2D.Double a,Point2D.Double b){int w=DrawingView.nativeWidth(),h=DrawingView.nativeHeight();if(removal==null||removalRevision!=DrawingView.nativeRevision()||removalLayer!=DrawingView.nativeActiveLayer()){removal=new BufferedImage(w,h,BufferedImage.TYPE_INT_ARGB);removalRevision=DrawingView.nativeRevision();removalLayer=DrawingView.nativeActiveLayer();}Graphics2D g=removal.createGraphics();g.setColor(new Color(255,30,110,160));g.setStroke(new BasicStroke(size,BasicStroke.CAP_ROUND,BasicStroke.JOIN_ROUND));g.draw(new Line2D.Double(a,b));g.fill(new Ellipse2D.Double(b.x-size/2.,b.y-size/2.,size,size));g.dispose();repaint();}
 public byte[] removalMask(){if(removal==null)return selection==null?null:selection.clone();if(removalRevision!=DrawingView.nativeRevision()||removalLayer!=DrawingView.nativeActiveLayer())return null;int w=removal.getWidth(),h=removal.getHeight();byte[] result=new byte[w*h];for(int y=0;y<h;y++)for(int x=0;x<w;x++)if((removal.getRGB(x,y)>>>24)!=0&&(selection==null||selection[y*w+x]!=0))result[y*w+x]=1;return result;}
 public void clearRemoval(){removal=null;repaint();}
 public void commitCurve(){if(curve.size()<2)return;curveBefore=DrawingView.nativeRevision();committedCurve.clear();committedCurve.addAll(curve);committedOthers.clear();for(var line:otherCurves)committedOthers.add(new ArrayList<>(line));DrawingView.nativeBeginEdit();DrawingView.nativeSetBrushSelection(selection);DrawingView.nativeBeginOpacityStroke(true);PathIterator path=curvePath().getPathIterator(null,.25);double[] xy=new double[6];double x=0,y=0;while(!path.isDone()){int type=path.currentSegment(xy);if(type==PathIterator.SEG_LINETO)DrawingView.nativeAntialiasedStroke((float)x,(float)y,(float)xy[0],(float)xy[1],size/2f,color,opacity,1,false);x=xy[0];y=xy[1];path.next();}DrawingView.nativeEndOpacityStroke();curve.clear();otherCurves.clear();refresh();}
 public void undo(){curve.clear();otherCurves.clear();if(DrawingView.nativeUndo()&&DrawingView.nativeRevision()==curveBefore){curve.addAll(committedCurve);for(var line:committedOthers)otherCurves.add(new ArrayList<>(line));}refresh();}
 public void cancelCurve(){curve.clear();otherCurves.clear();repaint();}
 private Path2D curvePath(){Path2D p=new Path2D.Double();for(var line:otherCurves)p.append(DesktopCurves.path(line,tensions),false);p.append(DesktopCurves.path(curve,tensions),false);return p;}
 @Override protected void paintComponent(Graphics graphics){super.paintComponent(graphics);if(DrawingView.nativeWidth()<1)return;Graphics2D g=(Graphics2D)graphics.create();g.transform(transform());int w=DrawingView.nativeWidth(),h=DrawingView.nativeHeight();Rectangle visible=g.getClipBounds().intersection(new Rectangle(0,0,w,h));if(visible.isEmpty()){g.dispose();return;}
  g.setColor(Color.WHITE);g.fillRect(0,0,w,h);g.setColor(new Color(225,225,225));for(int y=Math.max(0,visible.y/16*16);y<visible.y+visible.height;y+=16)for(int x=Math.max(0,visible.x/16*16);x<visible.x+visible.width;x+=16)if((x/16+y/16)%2==0)g.fillRect(x,y,16,16);
  int sample=1;while(sample<128&&visible.width/(double)sample*visible.height/sample>1000000)sample*=2;int rw=Math.max(1,(visible.width-1)/sample+1),rh=Math.max(1,(visible.height-1)/sample+1);
  int[] pixels=DrawingView.nativeSampleRegion(visible.x,visible.y,sample,rw,rh);if(pixels!=null){image=new BufferedImage(rw,rh,BufferedImage.TYPE_INT_ARGB);image.setRGB(0,0,rw,rh,pixels,0,rw);g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,zoom>=1?RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR:RenderingHints.VALUE_INTERPOLATION_BILINEAR);g.drawImage(image,visible.x,visible.y,rw*sample,rh*sample,null);}
  if(removal!=null&&removalRevision==DrawingView.nativeRevision()&&removalLayer==DrawingView.nativeActiveLayer())g.drawImage(removal,0,0,null);g.setColor(Color.CYAN);g.setStroke(new BasicStroke((float)(1/zoom)));if(selectionBounds!=null)g.draw(selectionBounds);if(!curve.isEmpty()){g.setColor(new Color(color,true));g.draw(curvePath());for(Point2D.Double p:curve)g.fill(new Ellipse2D.Double(p.x-4/zoom,p.y-4/zoom,8/zoom,8/zoom));}if(dragging&&!painting&&tool!=Tool.LINE&&start!=null&&current!=null)g.draw(tool==Tool.LASSO?lassoPath():shapePath());g.dispose();
 }
}
